1	//! Maps [`AgentEvent`]s onto AG-UI event frames, with bracketing.
2	//!
3	//! # Why bracketing lives here
4	//!
5	//! `TokenDelta`/`ReasoningDelta` are bare fragments, but AG-UI requires balanced
6	//! `*_START` … `*_CONTENT` … `*_END` triples, and `STEP_STARTED` has no
7	//! "turn finished" event to close it. [`EventMapper`] owns those pairings so no
8	//! transport has to.
9	//!
10	//! # Ordering
11	//!
12	//! `ToolCallDelta` is emitted while the model stream drains; the matching
13	//! `ToolCallItem` only afterwards. `TOOL_CALL_START` is therefore derived from the
14	//! deltas for a call id, and never from `ToolCallItem`, which would put START after
15	//! the ARGS frames it must precede. Usually the first delta opens the span, with the
16	//! name it carries (or `"unknown"`). Core gives `name: Some` exactly once per call,
17	//! but not always on the first delta (`paigasus-helikon-core/src/model.rs`). So when
18	//! an unnamed delta starts a new occurrence of a reused provider id (see below), the
19	//! mapper buffers the deltas of that occurrence until one of them carries the name;
20	//! then START opens the span with that name and the buffered args follow. If no delta
21	//! carries the name, the item, the result or the run end flushes the span.
22	//!
23	//! # One active tool-call span
24	//!
25	//! AG-UI permits a single active tool call at a time, but core's `ToolCallDelta`s for
26	//! different ids may interleave freely (`paigasus-helikon-core/src/model.rs:56`) and
27	//! its `ToolCallItem`s carry no ordering guarantee. Reconciling the two is what
28	//! [`EventMapper`]'s tool-call state exists for, and it owes an AG-UI client three
29	//! things: spans never overlap, one call id maps to exactly one span, and an id's
30	//! args reach the client in receipt order inside that span (a client concatenating
31	//! `TOOL_CALL_ARGS` deltas would otherwise rebuild malformed JSON). Deltas for an id
32	//! that arrive while another call holds the span are therefore buffered, not
33	//! interleaved, and replayed when that id takes the span or is flushed.
34	//!
35	//! # Call occurrences
36	//!
37	//! Provider call ids are unique **at item level** in one model stream (core's
38	//! accumulator merges deltas by id), but not across a run: Gemini numbers its calls
39	//! `fc_{n}` per response, so a later turn, or a handoff child, can reuse an id for a
40	//! different call. The mapper therefore keys its per-call state on the **AG-UI id**
41	//! of a call occurrence, not on the provider id. A new occurrence of provider id `x`
42	//! starts only when the events prove that a new call started: any `ToolCallDelta`
43	//! for `x` (named or not) when the current occurrence already had its item (the
44	//! item comes after all deltas of a call), a name-carrying `ToolCallDelta` for `x`
45	//! when the current occurrence already had one (core gives `name: Some` exactly once
46	//! per call), a `ToolCallItem` for `x` when the current occurrence already had its
47	//! item, or the first event for `x`. A name that arrives on a later delta belongs to
48	//! the occurrence that the earlier unnamed delta started. There is no reset at
49	//! `TurnStarted`: under `ParallelAgent` a sibling's `TurnStarted` can arrive between
50	//! one call's deltas and its item. The first occurrence of `x` keeps the id `x`; a
51	//! later one gets `x~n`, with the smallest `n` ≥ 2 that the run has not emitted yet,
52	//! so an alias never equals a provider id of the run. Every frame of the call
53	//! (`START`, `ARGS`, `END`, `RESULT`) uses that AG-UI id. A result for a provider id
54	//! with no occurrence uses the provider id, and the run counts that id as used.
55	//! AG-UI ids are unique per run only: each request gets a new mapper.
56	//!
57	//! A `helikon.approval` frame carries two ids. `tool_call_id` is the AG-UI id of the
58	//! current occurrence: it links the approval to the call's span. `call_id` is the
59	//! provider id: it matches `RunDeferred.calls[].call_id`, which the client uses to
60	//! resolve the deferral.
61	
62	use std::collections::{HashMap, HashSet};
63	
64	use paigasus_helikon_core::{AgentEvent, ContentPart, Item};
65	use serde_json::Value;
66	
67	use crate::agui::types::event;
68	
69	/// Which text-like pair is currently open.
70	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
71	enum OpenText {
72	    /// No text or thinking block is open.
73	    None,
74	    /// A `TEXT_MESSAGE_START` … `TEXT_MESSAGE_END` pair is open.
75	    Message,
76	    /// A `THINKING_TEXT_MESSAGE_START` … `THINKING_TEXT_MESSAGE_END` pair is open.
77	    Thinking,
78	}
79	
80	/// Which text-like pair [`EventMapper::open_text`] should open. Two variants, not
81	/// [`OpenText`]'s three — opening "no block" is not a request this method can be asked
82	/// to satisfy, so the type itself rules that call out rather than the body handling it.
83	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
84	enum TextKind {
85	    /// Open a `TEXT_MESSAGE_START` … `TEXT_MESSAGE_END` pair.
86	    Message,
87	    /// Open a `THINKING_TEXT_MESSAGE_START` … `THINKING_TEXT_MESSAGE_END` pair.
88	    Thinking,
89	}
90	
91	/// One occurrence of a provider call id: one tool call of the run.
92	#[derive(Debug, Clone)]
93	struct Occurrence {
94	    /// The AG-UI `toolCallId` of this occurrence: the provider id, or `{id}~{n}`.
95	    agui_id: String,
96	    /// Whether a `ToolCallDelta` with `name: Some(..)` was seen for this occurrence.
97	    named: bool,
98	    /// Whether the `ToolCallItem` of this occurrence was seen.
99	    item_seen: bool,
100	}
101	
102	/// Stateful `AgentEvent` → AG-UI frame mapper for exactly one run.
103	pub(crate) struct EventMapper {
104	    /// Client-supplied (or generated) thread id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
105	    thread_id: String,
106	    /// Client-supplied (or generated) run id, echoed in `RUN_STARTED`/`RUN_FINISHED`.
107	    run_id: String,
108	    /// Which text-like pair (message or thinking) is currently open, if any.
109	    open_text: OpenText,
110	    /// Id of the currently-open text or thinking message.
111	    current_message: String,
112	    /// Monotonic counter behind `msg-N` ids. Stream-local uniqueness is all AG-UI
113	    /// requires, and deterministic ids let tests assert exact frame sequences.
114	    next_message: u32,
115	    /// Whether the current turn's assistant text has already been streamed via
116	    /// `TokenDelta`. Distinct from `open_text == OpenText::Message`: a `ToolCallDelta`
117	    /// closes the text block (via `close_text`) well before the matching
118	    /// `MessageOutput` arrives, so checking "is a message open right now" would miss
119	    /// that this text was already streamed and re-emit it.
120	    streamed_text: bool,
121	    /// Provider call id → its latest occurrence. A provider id can repeat in one run
122	    /// (see the module doc), so every other per-call field is keyed on the
123	    /// occurrence's AG-UI id instead.
124	    current: HashMap<String, Occurrence>,
125	    /// Every AG-UI id that this run already gave to an occurrence. An alias is never
126	    /// one of these, so it never equals a provider id that the run emitted.
127	    used_ids: HashSet<String>,
128	    /// AG-UI id of the call currently being streamed — has an open `TOOL_CALL_START`
129	    /// and no `TOOL_CALL_END` yet. `None` if no call is currently open.
130	    open_call: Option<String>,
131	    /// Tool name per AG-UI call id, recorded from whichever `ToolCallDelta` first
132	    /// carries one. Only one delta of a call carries `name`, but the delta that finally
133	    /// opens that call's span may be a continuation (its buffer resuming, or a
134	    /// revisit), so the name has to be remembered rather than read off the delta at
135	    /// hand — otherwise those spans render as `"unknown"`.
136	    call_names: HashMap<String, String>,
137	    /// Calls whose deltas arrived while a *different* call was open, or while the
138	    /// call waits for its name (see `awaiting_name`): `(AG-UI id, accumulated args)`.
139	    /// AG-UI permits only one active tool-call span at a time, while core's `ToolCallDelta`s for different ids may interleave freely
140	    /// (`paigasus-helikon-core/src/model.rs:56`) — buffering instead of closing and
141	    /// resuming preserves every args chunk exactly once and never emits an unmatched
142	    /// `TOOL_CALL_END`. A `Vec`, not a map, so flush order is deterministic.
143	    buffered_calls: Vec<(String, String)>,
144	    /// AG-UI call ids whose span has been emitted *and* closed. A `ToolCallItem`
145	    /// arrives long after the deltas it describes, by which time the call's span may already
146	    /// be closed — by its own delta path or by a foreign event that interrupted it.
147	    /// Without this record the item's arm cannot tell "already rendered" from "never
148	    /// streamed, synthesize it", and emits a second complete span for one call.
149	    completed_calls: HashSet<String>,
150	    /// AG-UI ids of the occurrences of a reused provider id that an unnamed delta
151	    /// started, and that no delta has named yet. Their deltas are buffered, so that
152	    /// `TOOL_CALL_START` carries the name that arrives on a later delta.
153	    awaiting_name: HashSet<String>,
154	    /// Whether a `STEP_STARTED` is currently unmatched.
155	    step_open: bool,
156	}
157	
158	impl EventMapper {
159	    /// Create a mapper for one run.
160	    // Constructed by the AG-UI SSE endpoint (SMA-461 Task 6, src/agui/sse.rs) and the
161	    // AG-UI WebSocket endpoint (SMA-461 Task 7, src/agui/ws.rs), one per run in both.
162	    pub(crate) fn new(thread_id: String, run_id: String) -> Self {
163	        Self {
164	            thread_id,
165	            run_id,
166	            open_text: OpenText::None,
167	            current_message: String::new(),
168	            next_message: 0,
169	            streamed_text: false,
170	            current: HashMap::new(),
171	            used_ids: HashSet::new(),
172	            open_call: None,
173	            call_names: HashMap::new(),
174	            buffered_calls: Vec::new(),
175	            completed_calls: HashSet::new(),
176	            awaiting_name: HashSet::new(),
177	            step_open: false,
178	        }
179	    }
180	
181	    /// Map one event, emitting any bracketing frames it implies.
182	    // Called per event by both the AG-UI SSE endpoint (SMA-461 Task 6) and the AG-UI
183	    // WebSocket endpoint (SMA-461 Task 7) as each drains an `Agent` run.
184	    pub(crate) fn push(&mut self, ev: &AgentEvent) -> Vec<Value> {
185	        let mut out = Vec::new();
186	        match ev {
187	            AgentEvent::RunStarted { .. } => {
188	                out.push(event::run_started(&self.thread_id, &self.run_id));
189	            }
190	            AgentEvent::TurnStarted { .. } => {
191	                self.close_text(&mut out);
192	                // A tool-call span must not cross the `STEP_FINISHED`/`STEP_STARTED`
193	                // boundary below — it would close inside the *next* step.
194	                self.close_call(&mut out);
195	                self.close_step(&mut out);
196	                self.streamed_text = false;
197	                self.step_open = true;
198	                out.push(event::step_started("turn"));
199	            }
200	            AgentEvent::TokenDelta { text } => {
201	                self.close_call(&mut out);
202	                self.open_text(TextKind::Message, &mut out);
203	                if !text.is_empty() {
204	                    self.streamed_text = true;
205	                    out.push(event::text_message_content(&self.current_message, text));
206	                }
207	            }
208	            AgentEvent::ReasoningDelta { text } => {
209	                self.close_call(&mut out);
210	                self.open_text(TextKind::Thinking, &mut out);
211	                if !text.is_empty() {
212	                    out.push(event::thinking_content(&self.current_message, text));
213	                }
214	            }
215	            AgentEvent::ToolCallDelta {
216	                call_id,
217	                name,
218	                args_delta,
219	            } => {
220	                self.close_text(&mut out);
221	                let call_id = &self.occurrence_for_delta(call_id, name.is_some());
222	                if let Some(name) = name {
223	                    self.awaiting_name.remove(call_id);
224	                    self.call_names
225	                        .entry(call_id.clone())
226	                        .or_insert_with(|| name.clone());
227	                }
228	                if self.open_call.as_deref() == Some(call_id.as_str()) {
229	                    // A continuation of the currently-open call.
230	                    out.push(event::tool_call_args(call_id, args_delta));
231	                } else if self.open_call.is_none() && !self.awaiting_name.contains(call_id) {
232	                    // Nothing else is streaming and the call does not wait for its
233	                    // name: open this call now. If chunks for it were buffered while
234	                    // another call held the single active span, or while it waited
235	                    // for its name, replay them first — they were received before this one, and a
236	                    // client concatenating `TOOL_CALL_ARGS` deltas would otherwise
237	                    // rebuild the call's arguments out of order.
238	                    let buffered = self.take_buffered(call_id);
239	                    out.push(event::tool_call_start(
240	                        call_id,
241	                        self.name_of(call_id),
242	                        &self.current_message,
243	                    ));
244	                    if let Some(buffered) = buffered {
245	                        out.push(event::tool_call_args(call_id, &buffered));
246	                    }
247	                    out.push(event::tool_call_args(call_id, args_delta));
248	                    self.open_call = Some(call_id.clone());
249	                } else {
250	                    // A different call is streaming (AG-UI permits only one active
251	                    // span), or this new occurrence of a reused id waits for its
252	                    // name (`TOOL_CALL_START` carries it): buffer this id's content
253	                    // rather than emitting a START now — it is flushed as a complete span once
254	                    // its own `ToolCallItem` arrives, when a later delta resumes it
255	                    // above, or at the latest when the run ends.
256	                    match self.buffered_calls.iter_mut().find(|(id, _)| id == call_id) {
257	                        Some(entry) => entry.1.push_str(args_delta),
258	                        None => self
259	                            .buffered_calls
260	                            .push((call_id.clone(), args_delta.clone())),
261	                    }
262	                }
263	            }
264	            AgentEvent::ToolCallItem { item } => {
265	                self.close_text(&mut out);
266	                if let Item::ToolCall {
267	                    call_id,
268	                    name,
269	                    args,
270	                } = item
271	                {
272	                    let call_id = &self.occurrence_for_item(call_id);
273	                    if self.open_call.as_deref() == Some(call_id.as_str()) {
274	                        // The call this item describes is the one currently open.
275	                        self.close_call(&mut out);
276	                    } else if let Some(buffered) = self.take_buffered(call_id) {
277	                        // Deltas for this call were buffered while another call was
278	                        // open: flush the whole thing now as one complete,
279	                        // self-contained span. Nothing guarantees `ToolCallItem`s
280	                        // arrive in the order their calls opened, so close whatever
281	                        // is still open first — a complete span emitted inside
282	                        // another one would overlap.
283	                        self.close_call(&mut out);
284	                        self.emit_span(call_id, name, &buffered, &mut out);
285	                    } else if self.completed_calls.contains(call_id) {
286	                        // This call's span is already emitted and closed — by its own
287	                        // deltas above, or by a foreign event (a `TokenDelta`, another
288	                        // call's item) that had to close it to take the single active
289	                        // span. Synthesizing here would emit a second complete span
290	                        // for one call id.
291	                    } else {
292	                        // No deltas were streamed for this call (non-streaming
293	                        // provider): synthesize the whole triple from the item's own
294	                        // args so the client still sees a complete call — again, not
295	                        // nested inside whatever call is currently open.
296	                        self.close_call(&mut out);
297	                        self.emit_span(call_id, name, &args.to_string(), &mut out);
298	                    }
299	                } else {
300	                    out.push(self.custom("helikon.unknown", ev));
301	                }
302	            }
303	            AgentEvent::ToolOutputItem { item } => {
304	                self.close_call(&mut out);
305	                self.close_text(&mut out);
306	                if let Item::ToolResult { call_id, content } = item {
307	                    // The result belongs to the current occurrence of its provider id:
308	                    // in a sequential flow a result comes before the next call that
309	                    // could reuse the id. With no occurrence, the provider id is used,
310	                    // and the run counts it as used, so a later call with that id
311	                    // gets an alias.
312	                    if !self.current.contains_key(call_id) {
313	                        self.used_ids.insert(call_id.clone());
314	                    }
315	                    let call_id = self.agui_id_of(call_id);
316	                    if let Some(buffered) = self.take_buffered(&call_id) {
317	                        // Only possible under `ParallelAgent`: the call is still
318	                        // buffered. Flush it first, with its name, so its result never
319	                        // precedes its own span.
320	                        let name = self.name_of(&call_id).to_owned();
321	                        self.emit_span(&call_id, &name, &buffered, &mut out);
322	                    }
323	                    out.push(event::tool_call_result(&call_id, &text_of(content)));
324	                } else {
325	                    out.push(self.custom("helikon.unknown", ev));
326	                }
327	            }
328	            AgentEvent::MessageOutput { item } => {
329	                // Take the single active span before emitting anything: a synthesized
330	                // text triple nested inside an open `TOOL_CALL_START` would break
331	                // AG-UI's one-active-span rule.
332	                self.close_call(&mut out);
333	                if self.streamed_text {
334	                    // Deltas already streamed this text; only close it.
335	                    self.close_text(&mut out);
336	                } else {
337	                    // No deltas were emitted (non-streaming provider, workflow agent):
338	                    // synthesize the full triple, or the client renders nothing at all.
339	                    // Also closes any dangling thinking block if only `ReasoningDelta`s
340	                    // preceded this `MessageOutput` with no `TokenDelta` at all.
341	                    self.close_text(&mut out);
342	                    let content = match item {
343	                        Item::AssistantMessage { content, .. } => text_of(content),
344	                        _ => String::new(),
345	                    };
346	                    if !content.is_empty() {
347	                        let id = self.new_message_id();
348	                        out.push(event::text_message_start(&id));
349	                        out.push(event::text_message_content(&id, &content));
350	                        out.push(event::text_message_end(&id));
351	                    }
352	                }
353	                self.streamed_text = false;
354	            }
355	            AgentEvent::HandoffItem { .. } => out.push(self.custom("helikon.handoff", ev)),
356	            AgentEvent::AgentUpdated { .. } => out.push(self.custom("helikon.agent_updated", ev)),
357	            AgentEvent::GuardrailTriggered { .. } => out.push(self.custom("helikon.guardrail", ev)),
358	            AgentEvent::ApprovalRequested { call_id, .. } => {
359	                // Keep `call_id` as the provider id (it matches
360	                // `RunDeferred.calls[].call_id`). Add `tool_call_id`, the AG-UI id
361	                // of the current occurrence, so a client can connect the approval
362	                // to the call's span.
363	                let mut frame = self.custom("helikon.approval", ev);
364	                if let Some(value) = frame["value"].as_object_mut() {
365	                    value.insert(
366	                        "tool_call_id".to_owned(),
367	                        Value::String(self.agui_id_of(call_id)),
368	                    );
369	                }
370	                out.push(frame);
371	            }
372	            AgentEvent::PermissionDenied { .. } => {
373	                out.push(self.custom("helikon.permission_denied", ev));
374	            }
375	            AgentEvent::RepairStarted { .. } => out.push(self.custom("helikon.repair", ev)),
376	            AgentEvent::StructuredOutputFailed { .. } => {
377	                out.push(self.custom("helikon.structured_output_failed", ev));
378	            }
379	            AgentEvent::RunCompleted { .. } => {
380	                self.close_all(&mut out);
381	                self.streamed_text = false;
382	                out.push(event::run_finished(&self.thread_id, &self.run_id));
383	            }
384	            AgentEvent::UserMessageInjected { .. } => {
385	                out.push(self.custom("helikon.user_message_injected", ev));
386	            }
387	            // AG-UI has no "stopped" run event. A stop is a controlled end, not a
388	            // failure, so the stream ends with `RUN_FINISHED`; the CUSTOM frame before
389	            // it carries the reason and usage.
390	            AgentEvent::RunStopped { .. } => {
391	                self.close_all(&mut out);
392	                self.streamed_text = false;
393	                out.push(self.custom("helikon.run_stopped", ev));
394	                out.push(event::run_finished(&self.thread_id, &self.run_id));
395	            }
396	            AgentEvent::RunFailed { error } => {
397	                self.close_all(&mut out);
398	                self.streamed_text = false;
399	                out.push(event::run_error("AGENT_ERROR", error));
400	            }
401	            // `AgentEvent` is `#[non_exhaustive]`: a variant added to core later must
402	            // degrade to a lossless CUSTOM event rather than vanish.
403	            other => out.push(self.custom("helikon.unknown", other)),
404	        }
405	        out
406	    }
407	
408	    /// Close any pairs still open. Only needed when a stream ends without a terminal
409	    /// event; the terminal arms already close every open pair themselves.
410	    // Called by both the AG-UI SSE endpoint (SMA-461 Task 6) and the AG-UI WebSocket
411	    // endpoint (SMA-461 Task 7) once their channel from the underlying `Agent` stream
412	    // closes, in case that stream ended without a terminal event (e.g. a misbehaving
413	    // agent, or a connection dropped mid-run).
414	    pub(crate) fn finish(&mut self) -> Vec<Value> {
415	        let mut out = Vec::new();
416	        self.close_all(&mut out);
417	        out
418	    }
419	
420	    /// Build a `CUSTOM` frame carrying the full serialized event as its `value`.
421	    fn custom(&self, name: &str, ev: &AgentEvent) -> Value {
422	        event::custom(name, to_value(ev))
423	    }
424	
425	    /// Allocate the next deterministic `msg-N` id.
426	    fn new_message_id(&mut self) -> String {
427	        let id = format!("msg-{}", self.next_message);
428	        self.next_message += 1;
429	        id
430	    }
431	
432	    /// Ensure a text-like pair of kind `kind` is open, closing any different kind
433	    /// that is currently open first. A no-op if `kind` is already open.
434	    fn open_text(&mut self, kind: TextKind, out: &mut Vec<Value>) {
435	        let target = match kind {
436	            TextKind::Message => OpenText::Message,
437	            TextKind::Thinking => OpenText::Thinking,
438	        };
439	        if self.open_text == target {
440	            return;
441	        }
442	        self.close_text(out);
443	        let id = self.new_message_id();
444	        self.current_message = id.clone();
445	        match kind {
446	            TextKind::Message => out.push(event::text_message_start(&id)),
447	            TextKind::Thinking => out.push(event::thinking_start(&id)),
448	        }
449	        self.open_text = target;
450	    }
451	
452	    /// Close whichever text-like pair is currently open, if any.
453	    fn close_text(&mut self, out: &mut Vec<Value>) {
454	        match self.open_text {
455	            OpenText::Message => out.push(event::text_message_end(&self.current_message)),
456	            OpenText::Thinking => out.push(event::thinking_end(&self.current_message)),
457	            OpenText::None => {}
458	        }
459	        self.open_text = OpenText::None;
460	    }
461	
462	    /// Close whichever tool call is currently open, if any, and record it as done so
463	    /// its `ToolCallItem` — which always arrives later — does not render it twice.
464	    fn close_call(&mut self, out: &mut Vec<Value>) {
465	        if let Some(id) = self.open_call.take() {
466	            out.push(event::tool_call_end(&id));
467	            self.completed_calls.insert(id);
468	        }
469	    }
470	
471	    /// The AG-UI id for a `ToolCallDelta` of provider id `call_id`. Any delta, named
472	    /// or not, starts a new occurrence when the current one already had its
473	    /// `ToolCallItem` (the item comes after all deltas of a call), or when `call_id`
474	    /// has no occurrence yet. A name-carrying delta (`has_name`) also starts one when
475	    /// the current occurrence already had a name. An unnamed delta before the item
476	    /// stays on the current occurrence, and a name that arrives on a later delta
477	    /// attaches to the occurrence that the first delta started. When an unnamed
478	    /// delta starts a new occurrence because the current one already had its item
479	    /// (a reused id), the new occurrence waits for its name (`awaiting_name`).
480	    fn occurrence_for_delta(&mut self, call_id: &str, has_name: bool) -> String {
481	        let mut reused = false;
482	        if let Some(occ) = self.current.get_mut(call_id) {
483	            if !(occ.item_seen || (has_name && occ.named)) {
484	                occ.named |= has_name;
485	                return occ.agui_id.clone();
486	            }
487	            reused = occ.item_seen;
488	        }
489	        let agui_id = self.new_occurrence(call_id);
490	        if let Some(occ) = self.current.get_mut(call_id) {
491	            occ.named = has_name;
492	        }
493	        if reused && !has_name {
494	            self.awaiting_name.insert(agui_id.clone());
495	        }
496	        agui_id
497	    }
498	
499	    /// The AG-UI id for a `ToolCallItem` of provider id `call_id`. The item starts a
500	    /// new occurrence when the current one already had its item (a non-streamed call
501	    /// that reuses the id), or when `call_id` has no occurrence yet.
502	    fn occurrence_for_item(&mut self, call_id: &str) -> String {
503	        if let Some(occ) = self.current.get_mut(call_id) {
504	            if !occ.item_seen {
505	                occ.item_seen = true;
506	                return occ.agui_id.clone();
507	            }
508	        }
509	        let agui_id = self.new_occurrence(call_id);
510	        if let Some(occ) = self.current.get_mut(call_id) {
511	            occ.item_seen = true;
512	        }
513	        agui_id
514	    }
515	
516	    /// Start a new occurrence of provider id `call_id` and return its AG-UI id:
517	    /// `call_id` itself when the run has not used it, else `{call_id}~{n}` with the
518	    /// smallest `n` ≥ 2 that the run has not used.
519	    fn new_occurrence(&mut self, call_id: &str) -> String {
520	        let agui_id = if self.used_ids.contains(call_id) {
521	            (2u64..)
522	                .map(|n| format!("{call_id}~{n}"))
523	                .find(|alias| !self.used_ids.contains(alias))
524	                .expect("an unbounded range always yields an unused alias")
525	        } else {
526	            call_id.to_owned()
527	        };
528	        self.used_ids.insert(agui_id.clone());
529	        self.current.insert(
530	            call_id.to_owned(),
531	            Occurrence {
532	                agui_id: agui_id.clone(),
533	                named: false,
534	                item_seen: false,
535	            },
536	        );
537	        agui_id
538	    }
539	
540	    /// The AG-UI id of the current occurrence of provider id `call_id`, or `call_id`
541	    /// itself when it has none (a result for a call this mapper never saw).
542	    fn agui_id_of(&self, call_id: &str) -> String {
543	        self.current
544	            .get(call_id)
545	            .map_or_else(|| call_id.to_owned(), |occ| occ.agui_id.clone())
546	    }
547	
548	    /// Emit one complete, self-contained span for AG-UI id `call_id` and record it
549	    /// as closed.
550	    fn emit_span(&mut self, call_id: &str, name: &str, args: &str, out: &mut Vec<Value>) {
551	        out.push(event::tool_call_start(call_id, name, &self.current_message));
552	        out.push(event::tool_call_args(call_id, args));
553	        out.push(event::tool_call_end(call_id));
554	        self.completed_calls.insert(call_id.to_owned());
555	    }
556	
557	    /// The tool name recorded for AG-UI id `call_id`, falling back to `"unknown"` only
558	    /// when no delta for it ever carried one.
559	    fn name_of(&self, call_id: &str) -> &str {
560	        self.call_names
561	            .get(call_id)
562	            .map_or("unknown", String::as_str)
563	    }
564	
565	    /// Remove and return the args buffered for AG-UI id `call_id` while a different call
566	    /// held the active span, if any.
567	    fn take_buffered(&mut self, call_id: &str) -> Option<String> {
568	        let pos = self
569	            .buffered_calls
570	            .iter()
571	            .position(|(id, _)| id == call_id)?;
572	        Some(self.buffered_calls.remove(pos).1)
573	    }
574	
575	    /// Close a still-open `STEP_STARTED`, if any.
576	    fn close_step(&mut self, out: &mut Vec<Value>) {
577	        if self.step_open {
578	            out.push(event::step_finished("turn"));
579	            self.step_open = false;
580	        }
581	    }
582	
583	    /// Close every still-open pair: text/thinking, the open tool call, every
584	    /// still-buffered tool call (each as a complete span), then the step. Nothing
585	    /// may be left buffered once a run terminates.
586	    fn close_all(&mut self, out: &mut Vec<Value>) {
587	        self.close_text(out);
588	        self.close_call(out);
589	        for (id, args) in std::mem::take(&mut self.buffered_calls) {
590	            let name = self.name_of(&id).to_owned();
591	            self.emit_span(&id, &name, &args, out);
592	        }
593	        self.close_step(out);
594	    }
595	}
596	
597	/// Serialize an event for a `CUSTOM` frame's `value`, degrading to `null` rather than
598	/// failing — a frame with a null value still tells the client the event happened.
599	fn to_value(ev: &AgentEvent) -> Value {
600	    serde_json::to_value(ev).unwrap_or(Value::Null)
601	}
602	
603	/// Concatenate the text blocks of a content list, ignoring non-text parts.
604	fn text_of(content: &[ContentPart]) -> String {
605	    content
606	        .iter()
607	        .filter_map(|c| match c {
608	            ContentPart::Text { text } => Some(text.as_str()),
609	            _ => None,
610	        })
611	        .collect()
612	}
613	
614	#[cfg(test)]
615	mod tests {
616	    use super::*;
617	    use paigasus_helikon_core::{ContentPart, GuardrailKind, Item, TokenUsage};
618	    use std::collections::BTreeMap;
619	
620	    fn mapper() -> EventMapper {
621	        EventMapper::new("t1".to_owned(), "r1".to_owned())
622	    }
623	
624	    /// Collect the `type` of every frame produced for a sequence of events.
625	    fn types(events: &[AgentEvent]) -> Vec<String> {
626	        let mut m = mapper();
627	        let mut out = Vec::new();
628	        for e in events {
629	            for f in m.push(e) {
630	                out.push(f["type"].as_str().unwrap().to_owned());
631	            }
632	        }
633	        for f in m.finish() {
634	            out.push(f["type"].as_str().unwrap().to_owned());
635	        }
636	        out
637	    }
638	
639	    /// Like [`types`] but keeps the full frame, not just its `type` — for tests that
640	    /// need other fields (`toolCallId`, `delta`, …).

